using namespace recovery::v2;
using namespace recovery::v2::fuse;
namespace {
unsigned cases{},checks{};
void check(bool good,const char* name){++checks;if(!good)throw std::runtime_error(name);}
template<class F>void test(const char* name,F body){body();++cases;std::printf("PASS %s\n",name);}
ClockPair later(ClockPair p,Ns n){p.monotonic+=n;p.boottime+=n;return p;}
Nonce nonce(unsigned n){Nonce out{};for(unsigned k=0;k<4;++k)out[k]=std::uint8_t(n>>(8*k));out[31]=0xa5;return out;}
Timing timing(){auto t=syntheticTiming();t.grantLifetime=200;t.drainLead=60;t.stopGrace=20;t.killGrace=20;t.proofWindow=50;t.sleepAllowance=100;
 for(auto p:{&t.healthCadence,&t.challengeLifetime,&t.healthMaxAge,&t.grantLifetime,&t.drainLead,&t.startupBudget,&t.stopGrace,&t.killGrace,&t.proofWindow,&t.sleepAllowance,&t.clockSkew})*p*=1000;
 for(auto& p:t.workerPolicies)p.maxPendingAge*=1000;check(validTiming(t),"explicit synthetic timing valid");return t;}
SessionIdentity identity(){SessionIdentity i;text(i.session,"0123456789abcdef0123456789abcdef");text(i.boot,"01234567-89ab-cdef-0123-456789abcdef");text(i.invocation,"11111111111111111111111111111111");text(i.ownerInvocation,"22222222222222222222222222222222");text(i.mount,"/sys/fs/cgroup/unified");i.ownerPid=std::uint32_t(getpid());i.mainPid=i.ownerPid+1;i.device=21;i.inode=4097;i.ticket.fill(0x7b);check(setUnitNames(i)&&validIdentity(i),"identity valid");return i;}
Binding binding(const SessionIdentity& i){Binding b;b.mainPid=i.ownerPid+2;b.originalReference=71;text(b.invocation,"33333333333333333333333333333333");check(setUnitName(b,i),"fuse unit bound");return b;}
struct Notifier {unsigned calls{};std::uint64_t usec{};int result{1};static int notify(void* p,std::uint64_t u)noexcept{auto& n=*static_cast<Notifier*>(p);++n.calls;n.usec=u;return n.result;}};
struct Rig {
 SessionIdentity id{identity()};Binding bound{binding(id)};Timing t{timing()};Policy p{25000,35000,5000};
 ClockPair now{1000000,9000000,11};VerifiedPeer ownerPeer{std::uint32_t(getuid()),id.ownerPid,77,true};
 Notifier notification;Evidence evidence{bound,id,true,true,true,true,true,true};
 Lease lease{id,bound,7,t,p,ownerPeer,std::uint32_t(getuid()),now,&Notifier::notify,&notification};
 Message grant(unsigned seq=1){Message m;m.kind=Kind::Grant;m.identity=id;m.generation=7;m.sequence=seq;m.grant.challengeSequence=seq;m.grant.mainSequence=seq;m.grant.nonce=nonce(seq);m.grant.issued=now;m.grant.drainAt=later(now,t.grantLifetime-t.drainLead);m.grant.expires=later(now,t.grantLifetime);return m;}
 Wire raw(Message m){Wire w;check(encode(m,w),"test packet encodes");return w;}
 bool accept(Message m){return lease.accept(raw(m),ownerPeer,now,evidence);}
 bool cycle(unsigned seq){return accept(grant(seq));}
};
}
int main(){try{
 test("explicit_lease_inequality_and_no_default",[]{Rig r;check(validPolicy(r.p,r.t)&&!validPolicy({},r.t),"explicit policy only");auto t=syntheticTiming();check(!validPolicy({25000,35000,5000},t),"old microscopic profile cannot select a real lease");for(unsigned n=0;n<5;++n){auto p=r.p;if(n==0)p.leaseLifetime=30000;if(n==1)p.leaseLifetime=36000;if(n==2)p.dispatchMargin=0;if(n==3)p.bootstrapLifetime=40000;if(n==4)p.leaseLifetime=35001;check(!validPolicy(p,r.t),"unsafe deadline policy refused");}});
 test("original_owner_grant_and_one_notification",[]{Rig r;check(!r.lease.closed()&&r.cycle(1),"fresh owner grant accepted");check(r.notification.calls==1&&r.notification.usec==35,"short finite extension only");for(unsigned n=0;n<10;++n)check(r.lease.tick(r.now,r.evidence),"observer ticks alive");check(r.notification.calls==1,"observer ticks never renew");check(r.lease.outstandingUntil()==later(r.now,40000),"dispatch included in outstanding bound");});
 test("actual_owner_machine_progress_boundary",[]{Rig r;VerifiedPeer childPeer{0,r.id.mainPid,78,true};OwnerMachine owner(r.id,7,r.t,childPeer,0,r.now);ChildMachine child(r.id,7,r.t,r.ownerPeer,std::uint32_t(getuid()),r.now);Authority a{true,true,true,true};
 auto c=owner.challenge(r.now,a,nonce(1));Health h;h.captured=h.mainCompleted=r.now;h.mainSequence=1;h.workerCount=r.t.workers;auto response=child.respond(*c,r.ownerPeer,r.now,a,{true,h});auto grant=owner.acceptHealth(*response,childPeer,r.now,a);check(grant&&child.acceptGrant(*grant,r.ownerPeer,r.now,a)&&r.lease.accept(*grant,r.ownerPeer,r.now,r.evidence),"real protocol-issued grant renews");
 r.now=later(r.now,10000);c=owner.challenge(r.now,a,nonce(2));h.captured=r.now;auto stale=child.respond(*c,r.ownerPeer,r.now,a,{true,h});check(!stale&&child.reason()==Reason::NoMainProgress,"observer cannot produce second owner grant");check(r.lease.tick(r.now,r.evidence)&&r.notification.calls==1,"transport activity cannot refresh fuse");check(!r.lease.tick(later(r.now,25000),r.evidence)&&r.lease.fault()==Fault::LeaseExpired,"stalled foreground expires short fuse");});
 test("pinned_kernel_peer_connection_and_uid",[]{for(unsigned n=0;n<4;++n){Rig r;auto peer=r.ownerPeer;if(n==0)++peer.uid;if(n==1)++peer.pid;if(n==2)++peer.connection;if(n==3)peer.verified=false;check(!r.lease.accept(r.raw(r.grant()),peer,r.now,r.evidence)&&r.lease.fault()==Fault::Peer,"forged owner rejected");check(r.notification.calls==0&&!r.cycle(1),"cannot reconnect after rejection");}});
 test("binding_reference_profile_manager_power_loss_terminal",[]{for(unsigned n=0;n<10;++n){Rig r;if(n==0)r.evidence.originalOwnerReference=false;if(n==1)r.evidence.originalReaderReference=false;if(n==2)r.evidence.originalFuseReference=false;if(n==3)r.evidence.originalManager=false;if(n==4)r.evidence.verifiedProfile=false;if(n==5)r.evidence.completePowerBarrier=false;if(n==6)++r.evidence.fuse.originalReference;if(n==7)r.evidence.fuse.invocation[0]='4';if(n==8)++r.evidence.session.inode;if(n==9)++r.evidence.fuse.mainPid;check(!r.cycle(1)&&r.lease.closed()&&r.notification.calls==0,"authority loss denies extension");}});
 test("malformed_health_and_replay_never_renew",[]{for(unsigned n=0;n<7;++n){Rig r;auto m=r.grant();if(n==0)m.identity.ticket[0]^=1;if(n==1)++m.generation;if(n==2)m.sequence=2;if(n==3)m.grant.expires=later(m.grant.expires,1000);if(n==4)m.grant.issued=later(m.grant.issued,1000);if(n==5){check(r.cycle(1),"first accepted");}if(n==6){m.kind=Kind::Health;m.responseNonce=nonce(1);m.health.captured=m.health.mainCompleted=r.now;m.health.mainSequence=1;m.health.workerCount=r.t.workers;}check(!r.accept(m)&&r.lease.closed(),"invalid grant packet closes");check(r.notification.calls==(n==5?1u:0u),"no notification for rejected message");}});
 test("sequence_alone_cannot_renew_foreground_stall",[]{Rig r;check(r.cycle(1),"first accepted");r.now=later(r.now,10000);auto m=r.grant(2);m.grant.mainSequence=1;check(!r.accept(m)&&r.lease.fault()==Fault::Progress&&r.notification.calls==1,"main completion must advance");});
 test("nonce_and_challenge_are_nonreplayed",[]{for(unsigned n=0;n<2;++n){Rig r;check(r.cycle(1),"first accepted");r.now=later(r.now,10000);auto m=r.grant(2);if(n==0)m.grant.nonce=nonce(1);else m.grant.challengeSequence=1;check(!r.accept(m)&&r.lease.fault()==Fault::Sequence,"nonce or challenge reuse rejected");}});
 test("expiry_equality_and_bootstrap_bound",[]{Rig bootstrap;check(!bootstrap.lease.tick(later(bootstrap.now,25000),bootstrap.evidence)&&bootstrap.lease.fault()==Fault::StartupExpired,"finite bootstrap cannot renew itself");Rig r;check(r.cycle(1),"grant accepted");auto at=later(r.now,35000);check(!r.lease.tick(at,r.evidence)&&r.lease.fault()==Fault::LeaseExpired&&!r.cycle(2),"lease expiry equality irreversible");check(r.lease.outstandingUntil().monotonic<=r.lease.killBy().monotonic,"outstanding dispatch bound fits closure kill budget");});
 test("delayed_grant_keeps_original_issue_cutoff",[]{Rig r;auto m=r.grant();r.now=later(r.now,9000);check(r.accept(m)&&r.notification.usec==26,"transport delay deducted from extension");check(r.lease.outstandingUntil()==later(m.grant.issued,40000),"owner issue anchors deadline");});
 test("notification_absent_denied_or_failed_latches_closed",[]{for(int result:{0,-1,-13}){Rig r;r.notification.result=result;check(!r.cycle(1)&&r.lease.fault()==Fault::Notification&&r.lease.lastSequence()==0,"notification failure does not accept grant");check(!r.cycle(1)&&r.notification.calls==1,"failed notification cannot retry renewal");}});
 test("closure_preserves_original_clock_budget_no_reextension",[]{Rig r;check(r.cycle(1),"first accepted");Message m;m.kind=Kind::Closure;m.identity=r.id;m.generation=7;m.sequence=1;m.closure.identity=r.id;m.closure.generation=7;m.closure.closureGeneration=8;m.closure.lastGrantSequence=1;m.closure.closedAt=later(r.now,1000);m.closure.proofUntil=later(m.closure.closedAt,r.t.proofWindow);m.closure.reason=Reason::Requested;m.closure.originalReference=m.closure.clockReliable=true;r.now=later(r.now,5000);
 check(r.accept(m)&&r.lease.closed()&&r.lease.fault()==Fault::Closure,"authenticated closure accepted");check(r.lease.closedAt()==m.closure.closedAt&&r.lease.killBy()==later(m.closure.closedAt,40000),"original closure cutoff fixed");auto cutoff=r.lease.killBy();r.lease.disconnect(later(r.now,100000));check(r.lease.killBy()==cutoff&&r.notification.calls==1,"repeated closure cannot extend or restore");});
 test("paired_clock_discontinuity_and_epoch_loss",[]{for(unsigned n=0;n<3;++n){Rig r;check(r.cycle(1),"first accepted");auto bad=r.now;if(n==0)bad.boottime+=10000;if(n==1)--bad.monotonic;if(n==2)++bad.generation;check(!r.lease.tick(bad,r.evidence)&&r.lease.fault()==Fault::Clock,"clock discontinuity seals");}});
 test("real_seqpacket_owner_transport_eagain_data_eof",[]{Rig r;int fds[2];check(!socketpair(AF_UNIX,SOCK_SEQPACKET,0,fds),"private socketpair");OwnerChannel channel(fds[1],77,std::uint32_t(getuid()),r.id.ownerPid);check(channel.valid(),"kernel peer authenticated");check(channel.receive(r.lease,r.now,r.evidence)&&r.notification.calls==0,"EAGAIN does not renew");auto bytes=r.raw(r.grant());check(send(fds[0],bytes.data(),bytes.size(),0)==ssize_t(bytes.size()),"fixed grant sent");check(channel.receive(r.lease,r.now,r.evidence)&&r.notification.calls==1,"real received grant renews once");close(fds[0]);check(!channel.receive(r.lease,r.now,r.evidence)&&r.lease.closed(),"EOF terminal");});
 test("actual_kernel_channel_rejects_wrong_pid_type_and_truncation",[]{for(unsigned n=0;n<3;++n){Rig r;int fds[2];check(!socketpair(AF_UNIX,n==1?SOCK_STREAM:SOCK_SEQPACKET,0,fds),"socket pair");OwnerChannel channel(fds[1],77,std::uint32_t(getuid()),r.id.ownerPid+(n==0?1:0));if(n<2)check(!channel.valid(),"wrong kernel peer or socket type refused");else {std::array<char,WireBytes+1> tooLarge{};check(send(fds[0],tooLarge.data(),tooLarge.size(),0)==ssize_t(tooLarge.size()),"oversized packet sent");check(!channel.receive(r.lease,r.now,r.evidence)&&r.lease.closed(),"MSG_TRUNC seals transport");}close(fds[0]);}});
 test("inherited_owner_socket_does_not_authenticate_descendant",[]{Rig r;int fds[2];check(!socketpair(AF_UNIX,SOCK_SEQPACKET,0,fds),"owner socket pair");OwnerChannel channel(fds[1],77,std::uint32_t(getuid()),r.id.ownerPid);auto bytes=r.raw(r.grant());pid_t child=fork();check(child>=0,"inert child created");if(!child){auto n=send(fds[0],bytes.data(),bytes.size(),0);_exit(n==ssize_t(bytes.size())?0:1);}int status{};check(waitpid(child,&status,0)==child&&WIFEXITED(status)&&WEXITSTATUS(status)==0,"inert child sent and reaped");check(!channel.receive(r.lease,r.now,r.evidence)&&r.lease.closed()&&r.notification.calls==0,"kernel message PID rejects inherited socket writer");close(fds[0]);});
 test("unexpected_received_file_descriptors_are_rejected",[]{Rig r;int fds[2],pipefd[2];check(!socketpair(AF_UNIX,SOCK_SEQPACKET,0,fds)&&!pipe(pipefd),"bounded fd fixture");OwnerChannel channel(fds[1],77,std::uint32_t(getuid()),r.id.ownerPid);auto bytes=r.raw(r.grant());iovec iov{bytes.data(),bytes.size()};msghdr message{};message.msg_iov=&iov;message.msg_iovlen=1;alignas(cmsghdr) std::array<char,CMSG_SPACE(sizeof(int))> ancillary{};message.msg_control=ancillary.data();message.msg_controllen=ancillary.size();auto c=CMSG_FIRSTHDR(&message);c->cmsg_level=SOL_SOCKET;c->cmsg_type=SCM_RIGHTS;c->cmsg_len=CMSG_LEN(sizeof(int));std::memcpy(CMSG_DATA(c),&pipefd[0],sizeof(int));check(sendmsg(fds[0],&message,0)==ssize_t(bytes.size()),"descriptor packet sent");check(!channel.receive(r.lease,r.now,r.evidence)&&r.lease.closed()&&r.notification.calls==0,"unexpected rights rejected and closed");close(pipefd[0]);close(pipefd[1]);close(fds[0]);});
 test("actual_notify_payload_only_finite_runtime_extension",[]{char temp[]="/tmp/lease-fuse-notify.XXXXXX";char* root=mkdtemp(temp);check(root,"new private fixture");std::string path=std::string(root)+"/notify";int fd=socket(AF_UNIX,SOCK_DGRAM|SOCK_CLOEXEC,0);check(fd>=0,"fixture datagram");sockaddr_un address{};address.sun_family=AF_UNIX;check(path.size()<sizeof(address.sun_path),"fixture path bounded");std::memcpy(address.sun_path,path.c_str(),path.size()+1);check(!bind(fd,reinterpret_cast<sockaddr*>(&address),sizeof(address)),"private notify receiver");const char* old=getenv("NOTIFY_SOCKET");std::string saved=old?old:"";check(!setenv("NOTIFY_SOCKET",path.c_str(),1),"fixture notify address");check(notifyRuntime(nullptr,35)>0,"actual sd_notify sends");char bytes[100]{};auto n=recv(fd,bytes,sizeof(bytes),MSG_DONTWAIT);check(n>0&&std::string_view(bytes,std::size_t(n))=="EXTEND_TIMEOUT_USEC=35","only finite runtime extension payload");if(old)setenv("NOTIFY_SOCKET",saved.c_str(),1);else unsetenv("NOTIFY_SOCKET");close(fd);unlink(path.c_str());rmdir(root);});
 test("fixed_memory_short_lease_350_seconds_virtual",[]{Rig r;
 for(auto p:{&r.t.healthCadence,&r.t.challengeLifetime,&r.t.healthMaxAge,&r.t.grantLifetime,&r.t.drainLead,&r.t.startupBudget,&r.t.stopGrace,&r.t.killGrace,&r.t.proofWindow,&r.t.sleepAllowance,&r.t.clockSkew})*p*=1000;
 for(auto& p:r.t.workerPolicies)p.maxPendingAge*=1000;r.p={25000000,35000000,5000000};
 Lease sustained(r.id,r.bound,7,r.t,r.p,r.ownerPeer,std::uint32_t(getuid()),r.now,&Notifier::notify,&r.notification);
 auto start=r.now;constexpr unsigned cycles=35000;for(unsigned n=1;n<=cycles;++n){check(sustained.accept(r.raw(r.grant(n)),r.ownerPeer,r.now,r.evidence),"bounded sustained grant");check(sustained.outstandingUntil().monotonic-r.now.monotonic==40000000,"outstanding lease fixed");r.now=later(r.now,10000000);}check(r.now.monotonic-start.monotonic==350000000000ULL,"350 virtual seconds exceeds V1 limit");check(r.notification.calls==cycles&&sustained.lastSequence()==cycles,"one finite notify per true progress");sustained.disconnect(r.now);check(sustained.closed()&&!sustained.accept(r.raw(r.grant(cycles+1)),r.ownerPeer,r.now,r.evidence),"sustained closure remains finite");});
 std::printf("LEASE_FUSE_V2_PASS cases=%u checks=%u original_manager_gate=FAILED_UNCHANGED production_timing=UNSELECTED physical=NOT_RUN restoration_authority=NONE\n",cases,checks);return 0;
}catch(const std::exception& e){std::fprintf(stderr,"LEASE_FUSE_V2_FAIL %s\n",e.what());return 1;}}
